571	    /** A move of one of several claims moved together: by the rules of {@link #reassign}, except that a
572	     * claim that already belongs to the person goes through (it is listed as the person's newest claim,
573	     * and recorded), even when it is dated in a closed period, so long as it is not due by in one. */
574	    @Transactional
575	    public Claim reassignOfBulk(String sheetId, String user, long claimId, long personId) {
576	        return move(sheetId, user, claimId, personId, true);
577	    }
