579	    private Claim move(String sheetId, String user, long claimId, long personId, boolean samePerson) {
580	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
581	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
582	        refuseClosed(sheetId, claim.getDueBy());
583	        // A claim that stays with its own person takes nothing out of the closed period its date is in.
584	        if (claim.getPersonId() != personId) refuseClosed(sheetId, claim.getDate());
585	        ClaimStatus status = claim.getStatus();
586	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
587	                || claim.isCorrection() || (!samePerson && claim.getPersonId() == personId)) {
588	            throw new ClaimReassignException();
589	        }
590	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
591	                .orElseThrow(PersonNotFoundException::new);
592	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
593	        to.requireClaimable(claim.getDate());
594	        RollupService.Snapshot before = rollup.snapshot(sheetId);
595	        claim.setPersonId(to.getId());
596	        claim.unbind();
597	        if (claim.getNumber() != null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
598	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
599	        claims.flush();
600	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
601	        rollup.recordSince(sheetId, user, before);
602	        return claim;
603	    }
