629	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
630	     * 7 days after the date its status log first shows it SETTLED. */
631	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
632	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
633	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
634	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
635	                .map(ClaimLog::getDate)
636	                .findFirst()
637	                .orElseThrow(ClaimStatusChangeException::new);
638	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
639	    }
